module probe;
  logic [2:0] a, d;
  logic signed [1:0] b, c;
  typedef bit signed [1:0] s2_t;
  typedef bit [2:0] u3_t;
  typedef bit signed [2:0] s3_t;
  typedef bit [1:0] u2_t;
  s2_t sa[0:0]; u3_t ub[0:0]; s3_t sc[0:0]; u2_t ud[0:0];
  initial begin
    a = 3'b111; b = 2'b11; c = 2'b11; d = 3'b111;
    sa[0] = 2'b11; ub[0] = 3'b111; sc[0] = 3'b111; ud[0] = 2'b11;
    $display("A array=%b listed=%b equality=%b", a inside {sa},
             a inside {sa[0]}, a ==? sa[0]);
    $display("B array=%b listed=%b equality=%b", b inside {ub},
             b inside {ub[0]}, b ==? ub[0]);
    $display("C array=%b listed=%b equality=%b", c inside {sc},
             c inside {sc[0]}, c ==? sc[0]);
    $display("D array=%b listed=%b equality=%b", d inside {ud},
             d inside {ud[0]}, d ==? ud[0]);
    $finish;
  end
endmodule

